contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public entry carrying out the property test.
    // Params:
    //  betAmt: amount to set as bet limit and to send when calling wager
    // Function is payable so the harness can fund this contract before calling wager and potential donate/payouts.
    function run(uint256 betAmt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (betAmt)); require(betAmt <= 1000000000000000000000000000000);
        // need funds to wager
        require(address(this).balance >= betAmt, "need funds");

        // Make contract open and set the bet limit so wager()/play() can be exercised.
        c.OpenToThePublic(); if (__ESBMC_reverted()) return;
        c.AdjustBetAmounts(betAmt); if (__ESBMC_reverted()) return;

        // Ensure we are not already recorded as player and contract has some balance baseline
        uint256 beforeBal = address(c).balance;
        bool beforeRecorded = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;

        // Try to place a wager of exactly betAmt
        bool wagerReverted;
        c.wager{value: betAmt}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            wagerReverted = true;
        } else {
            wagerReverted = false;
        }

        // If wager reverted we cannot call play as player because wager didn't record; in that case we still attempt play to observe behavior.
        bool playReverted;
        c.play(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            playReverted = true;
        } else {
            playReverted = false;
        }

        uint256 afterBal = address(c).balance;
        bool afterRecorded = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;

        // Assert the invariant: whenever play() did not revert, either the contract balance decreased (some payment occurred)
        // or the caller is no longer recorded as a player (their wager cleared). This must hold for all inputs.
        assert(
            playReverted
            || (afterBal < beforeBal)
            || (afterRecorded == false)
        );
    }

    // Accept Ether when c pays out.
    receive() external payable {}
}

