// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 betAmt) internal {
        betAmt = bound(betAmt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= betAmt);
        try c.OpenToThePublic() {} catch { return; }
        try c.AdjustBetAmounts(betAmt) {} catch { return; }
        uint256 beforeBal = address(c).balance;
        bool beforeRecorded;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { beforeRecorded = __r; } catch { return; }
        bool wagerReverted;
        try c.wager{value: betAmt}() {
            wagerReverted = false;
        } catch {
            wagerReverted = true;
        }
        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }
        uint256 afterBal = address(c).balance;
        bool afterRecorded;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { afterRecorded = __r; } catch { return; }
        assertTrue(playReverted
            || (afterBal < beforeBal)
            || (afterRecorded == false));
    }

    function testFuzz_run(uint256 betAmt) public {
        _run(betAmt);
    }

    receive() external payable {}
}
